INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (215, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI161', 'Italian Opera Aria featuring Italian vocals. Full orchestra provides rich sustained harmonic support with sweeping string sections and dramatic brass punctuations. Grand piano delivers arpeggiated accompaniment with crystalline upper-register runs and supportive chord voicings. Harp adds delicate glissando embellishments and shimmering plucked accents between vocal phrases. The vocals feature a powerful operatic delivery with soaring sustained high notes and expressive vibrato. The arrangement is grand and dramatic, building from intimate recitative passages to full orchestral climax. 68 BPM in Ab Major, 3/4 time signature.', '[Verse 1]
Nella notte silente io canto
Una voce che sale al cielo
Le stelle mi guardano in pianto
Mentre il cuore si copre di velo

[Chorus]
O luce eterna, guidami tu
Attraverso l''ombra e il dolore
Finché la mia voce non tace più
Canterò per il nostro amore

[Verse 2]
Il vento porta le mie parole
Oltre le montagne e il mare
Dove nasce e muore il sole
Là il mio cuore vuole andare

[Chorus]
O luce eterna, guidami tu
Attraverso l''ombra e il dolore
Finché la mia voce non tace più
Canterò per il nostro amore', 'Italian Opera Aria', 68, 'Ab Major', 'S_INST200 session5 Through-composed, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (216, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI162', 'Italian Art Song featuring Italian vocals. Piano provides gentle arpeggiated accompaniment with warm sustained chords and delicate melodic counterlines that support the vocal melody. Strings deliver soft sustained harmonic pads with legato bowing and subtle crescendos that swell beneath the voice. Oboe enters with lyrical counter-phrases and warm sustained tones that interweave with the vocal line. The vocals feature an intimate, refined delivery with controlled vibrato and clear diction. The arrangement is elegant and restrained, with the piano leading the harmonic narrative. 58 BPM in Db Major, 6/8 time signature.', '[Verse 1]
Dolce mattina, il sole sorge piano
Sopra i campi dorati dal grano
L''aria profuma di rose e di miele
E il mio cuore si apre fedele

[Verse 2]
Scorre il fiume tra le verdi colline
Porta con sé le speranze divine
Ogni foglia sussurra una storia
Di bellezza, di pace, di gloria

[Verse 3]
Quando la sera dipinge il tramonto
Io rimango in silenzio e racconto
Alle stelle che brillano in cielo
Che la vita è un prezioso gioiello', 'Italian Art Song', 58, 'Db Major', 'S_INST200 session5 Strophic, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (217, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI163', 'French Chanson featuring French vocals. Accordion plays warm sustained chords with gentle musette vibrato and flowing melodic passages that breathe with the vocal phrasing. Nylon-string guitar provides soft fingerpicked arpeggios with round woody tone and understated rhythmic comping. Upright bass delivers a smooth walking foundation with legato quarter notes and warm low-end support. The vocals feature an intimate conversational delivery with breathy tone and subtle melodic embellishments. The arrangement is Parisian and nostalgic, with sparse instrumentation that frames the voice. 90 BPM in F Minor, 3/4 time signature.', '[Verse 1]
Sous les toits gris de la ville endormie
Je marche seul dans la pluie qui murmure
Les réverbères dessinent ma vie
En ombres d''or sur les vieux murs

[Chorus]
Et je chante pour oublier
Les jours passés, les nuits d''été
Une chanson dans le vent léger
Qui porte au loin ma liberté

[Verse 2]
Un café noir au coin de la rue
Où les amants se disent adieu
Le temps s''arrête, la nuit est venue
Et dans mon verre brille un peu de bleu

[Chorus]
Et je chante pour oublier
Les jours passés, les nuits d''été
Une chanson dans le vent léger
Qui porte au loin ma liberté', 'French Chanson', 90, 'F Minor', 'S_INST200 session5 Strophic, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (218, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI164', 'Spanish Bolero featuring Spanish vocals. Nylon-string guitar plays gentle fingerpicked arpeggios with warm nylon-string resonance and subtle rasgueado flourishes between vocal phrases. Congas provide a soft syncopated pattern with delicate finger rolls and muted tones that maintain a swaying pulse. Upright bass delivers deep sustained root notes with legato slides and warm rounded tone. The vocals feature a passionate yet restrained delivery with expressive rubato phrasing and gentle vibrato. The arrangement is intimate and romantic, with the guitar and voice sharing the melodic spotlight. 62 BPM in A Minor, 4/4 time signature.', '[Verse 1]
Bajo la luna que alumbra el camino
Tu recuerdo me sigue sin fin
Cada estrella susurra tu nombre
Cada noche te vuelvo a sentir

[Chorus]
Y te busco en el viento y la lluvia
En el mar que se pierde en la arena
Eres tú mi canción y mi calma
Eres tú mi dulzura y mi pena

[Verse 2]
Pasan los días como hojas al río
Pero tu voz no se puede borrar
En mis sueños te encuentro dormida
En mis labios te vuelvo a besar

[Chorus]
Y te busco en el viento y la lluvia
En el mar que se pierde en la arena
Eres tú mi canción y mi calma
Eres tú mi dulzura y mi pena', 'Spanish Bolero', 62, 'A Minor', 'S_INST200 session5 Strophic, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (219, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI165', 'Brazilian Bossa Nova featuring Portuguese vocals. Nylon-string guitar plays characteristic syncopated comping with muted thumb-bass patterns and gentle chord voicings that create the signature bossa groove. Electric piano provides warm sustained chord pads with soft tremolo and bell-like upper-register accents. Soft percussion delivers a subtle brushed pattern with light shaker and muted rim clicks. The vocals feature a soft whispering tone with relaxed phrasing and natural speech-like delivery. The arrangement is smooth and understated, with the guitar''s rhythmic pattern anchoring a warm harmonic flow. 72 BPM in Db Major, 4/4 time signature.', '[Verse 1]
A brisa do mar me leva
Por caminhos de luz e sal
O sol desenha na areia
Um sorriso de coral

[Chorus]
E eu canto essa canção
Que nasce do coração
Um som que o vento carrega
Pra além da solidão

[Verse 2]
As ondas vêm e vão embora
Como o tempo que não para
Mas a saudade que demora
É a mais bonita e rara

[Chorus]
E eu canto essa canção
Que nasce do coração
Um som que o vento carrega
Pra além da solidão', 'Brazilian Bossa Nova', 72, 'Db Major', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (220, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI166', 'German Lied featuring German vocals. Grand piano plays expressive arpeggiated figures with rich pedal-sustained harmonies and sensitive dynamic shading that follows the vocal contour. The vocals feature a clear lyrical delivery with precise diction and controlled vibrato on sustained notes. The arrangement is intimate and classical, with the piano providing both harmonic foundation and melodic commentary. 55 BPM in Eb Major, 3/4 time signature.', '[Verse 1]
Der Abend sinkt auf stille Felder
Der Mond steigt auf im Silberlicht
Durch dunkle Wälder, alte Wälder
Ein leises Lied die Stille bricht

[Verse 2]
Die Blumen schlafen an dem Bache
Der sanft durch grüne Wiesen fließt
Ich steh allein und halte Wache
Bis sich mein Herz im Traum ergießt

[Verse 3]
O komm zurück, du ferne Stunde
Da wir noch hand in Hand gegangen
Die Worte still auf meinem Munde
Nach dir wird ewig mein Verlangen', 'German Lied', 55, 'Eb Major', 'S_INST200 session5 Through-composed, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (221, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI167', 'Hindi Film Song featuring Hindi vocals. Sitar plays ornamental melodic phrases with buzzing sympathetic strings and expressive meend bends that embellish the vocal melody. Tabla provides a driving rhythmic cycle with crisp finger strokes and resonant bass hits that propel the song forward. Strings deliver lush sustained arrangements with sweeping crescendos and romantic harmonic movements. The vocals feature an emotive Bollywood-style delivery with melismatic runs and dramatic dynamic contrasts. The arrangement is cinematic and lush, blending Indian classical ornamentation with orchestral grandeur. 95 BPM in Bb Minor, 4/4 time signature.', '[Verse 1]
Chaandni raat mein tanha main hoon
Teri yaad ka saaya sang mein hai
Hawa mein teri khushboo ghuli
Har pal mein tera rang mein hai

[Chorus]
Tu meri dhun hai, tu meri taan
Tere bina adhoora ye jahaan
Sunog meri dil ki pukaar
Tu hi mera pyaar, tu hi mera pyaar

[Verse 2]
Baarish ki boondein gaati hain
Woh geet jo humne gaaye the
Sapnon mein aaj bhi aati hain
Woh raahein jo saath chalaaye the

[Chorus]
Tu meri dhun hai, tu meri taan
Tere bina adhoora ye jahaan
Sunog meri dil ki pukaar
Tu hi mera pyaar, tu hi mera pyaar', 'Hindi Film Song', 95, 'Bb Minor', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (222, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI168', 'Swahili Pop featuring Swahili vocals. Electric guitar plays bright clean rhythmic patterns with staccato muted strums and melodic fills between vocal phrases. Bass guitar provides a warm syncopated groove with fingered eighth-note patterns and occasional slides that anchor the low end. Percussion delivers a layered pattern with shakers, congas, and crisp snare accents that create an infectious danceable feel. The vocals feature a warm melodic delivery with call-and-response phrasing and rhythmic syllabic patterns. The arrangement is sunny and uplifting, driven by the guitar''s bright tone and rhythmic percussion. 110 BPM in Ab Major, 4/4 time signature.', '[Verse 1]
Jua linachomoza mapema
Ndege wanaimba kwa furaha
Moyo wangu umejaa neema
Kila siku ni baraka safi sana

[Chorus]
Twende pamoja, twende mbele
Maisha ni safari nzuri
Kwa upendo na kwa amani
Tuimbe wimbo wa furaha

[Verse 2]
Mawimbi ya bahari yanacheza
Upepo unavuma taratibu
Watoto wanacheka wanakimbia
Dunia nzima inatabasamu

[Chorus]
Twende pamoja, twende mbele
Maisha ni safari nzuri
Kwa upendo na kwa amani
Tuimbe wimbo wa furaha', 'Swahili Pop', 110, 'Ab Major', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (223, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI169', 'Arabic Pop featuring Arabic vocals. Oud plays melodic phrases with rapid tremolo picking and ornamental grace notes that wind through maqam intervals. Darbuka provides a driving rhythmic pattern with crisp finger rolls and sharp tek accents that create a propulsive Middle Eastern groove. Strings deliver lush sustained harmonic support with sweeping melodic counterlines and dramatic unison passages. The vocals feature a powerful emotive delivery with melismatic ornamental runs and quarter-tone inflections. The arrangement is rich and passionate, blending traditional maqam color with modern pop production. 95 BPM in Bb Phrygian, 4/4 time signature.', '[Verse 1]
Fi layl el hawa el hadi
Samaat sawtak min baeed
Qalbi yenadi yenadi
Wel shoug fi rouhi jadeed

[Chorus]
Ya habibi ya nour eini
Inta el hob wel amaan
Khodni maak lel dunya tani
We neish sawa kol zamaan

[Verse 2]
El qamar yedhak fil sama
Wel nujoom tenawwar el leil
Ma fi shi ahla min hawa
Yejmaana taht el nakheel

[Chorus]
Ya habibi ya nour eini
Inta el hob wel amaan
Khodni maak lel dunya tani
We neish sawa kol zamaan', 'Arabic Pop', 95, 'Bb Phrygian', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (224, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI170', 'K-Ballad featuring Korean vocals. Grand piano plays arpeggiated chord progressions with warm pedal-sustained resonance and gentle melodic fills between vocal phrases. Strings provide lush sustained harmonic pads with slow swelling crescendos and delicate pizzicato accents. Gentle drums deliver a soft brushed pattern with understated kick and rim click that barely mark the pulse. The vocals feature a breathy intimate tone with emotional vibrato on sustained notes and a soaring chest-to-head voice lift in the chorus. The arrangement is spacious and emotionally transparent, with the piano and voice carrying the narrative. 68 BPM in Db Major, 4/4 time signature.', '[Verse 1]
텅 빈 거리 위에 내리는 빗소리
너의 목소리가 들리는 것 같아
창문에 맺힌 작은 물방울처럼
내 마음에도 눈물이 고여

[Chorus]
돌아와줘 내 곁으로
이 밤이 지나기 전에
너 없인 아무것도 아닌
이 세상이 너무 차가워

[Verse 2]
함께 걸었던 그 길을 지나며
우리 웃었던 그때를 떠올려
바람에 실려 오는 네 향기에
멈출 수 없는 그리움이 번져

[Chorus]
돌아와줘 내 곁으로
이 밤이 지나기 전에
너 없인 아무것도 아닌
이 세상이 너무 차가워', 'K-Ballad Vocal', 68, 'Db Major', 'S_INST200 session5 Verse-Chorus-Bridge, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (225, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI171', 'K-Trot featuring Korean vocals. Accordion plays bright staccato chord patterns with rhythmic pumping accents and occasional melodic fills that bridge verse to chorus. Saxophone provides warm melodic counter-phrases with breathy sustained tones and smooth legato runs. Electric bass delivers a bouncing foxtrot-style walking line with disco-influenced syncopation and bright fingered attack. The vocals feature a vibrant emotive delivery with characteristic trot vibrato and dramatic emotional peaks. The arrangement is festive and driving, with the accordion and bass creating an infectious two-beat groove. 122 BPM in A Major, 4/4 time signature.', '[Verse 1]
항구의 불빛이 반짝이는 밤에
파도 소리에 실려 오는 그 노래
소주 한 잔에 녹아드는 그리움
당신 생각에 오늘도 취해요

[Chorus]
아이고 좋다 이 밤이 좋다
신나게 한번 불러보자
인생은 짧고 노래는 길어
오늘 밤 함께 춤을 추자

[Verse 2]
기차는 떠나고 역엔 나 혼자
손수건 흔들며 울었던 그 날이
세월이 흘러도 잊을 수 없는
첫사랑 그때 그 아름다운 얼굴

[Chorus]
아이고 좋다 이 밤이 좋다
신나게 한번 불러보자
인생은 짧고 노래는 길어
오늘 밤 함께 춤을 추자', 'K-Trot Vocal', 122, 'A Major', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (226, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI172', 'Chinese Ballad featuring Mandarin vocals. Erhu plays a mournful sustained counter-melody with expressive vibrato and long bowed phrases that shadow the vocal line. Piano provides gentle arpeggiated accompaniment with warm pedal-sustained chords and soft melodic responses. Strings deliver lush harmonic pads with slow crescendos and delicate tremolo passages. The vocals feature a clear emotive tone with controlled vibrato and soaring high notes that convey deep longing. The arrangement is cinematic and tender, with the erhu and voice sharing the emotional weight. 70 BPM in F# Minor, 4/4 time signature.', '[Verse 1]
月光洒在窗台上
思念像风吹过脸庞
远方的你可曾听见
我在夜里轻轻唱

[Chorus]
千山万水隔不断
心中那份深深的爱
等到花开春风暖
你我重逢在梦的海

[Verse 2]
落叶飘零秋意浓
往事如烟却在心中
你的笑容像阳光
温暖了我整个冬

[Chorus]
千山万水隔不断
心中那份深深的爱
等到花开春风暖
你我重逢在梦的海', 'Chinese Ballad', 70, 'F# Minor', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (227, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI173', 'Irish Gaelic Folk featuring Irish Gaelic vocals. Tin whistle plays bright ornamental melodic phrases with rapid triplet runs and crisp tongued articulations that dance across the compound meter. Bodhrán provides a driving rhythmic pulse with tipper rolls and accented downbeats that propel the jig-like feel. Acoustic guitar delivers warm strummed accompaniment with open-tuning resonance and percussive muted strums. The vocals feature a clear unaffected delivery with natural ornamentation and sean-nós style free phrasing. The arrangement is rousing and organic, with the whistle and voice trading melodic leads. 100 BPM in A Major, 6/8 time signature.', '[Verse 1]
Ar maidin gheal ag éirí gréine
Bhí an drúcht ar bharr an fhéir
Is mé ag siúl trí ghleannta Éireann
Faoi sholas óir an lae

[Chorus]
Seo í mo amhrán, seo í mo ghlór
Ag canadh le gaoth an tsléibhe
Ó chroí go croí, ó ghlúin go glúin
Beidh an ceol seo beo go deo

[Verse 2]
Na tonnta ag briseadh ar an gcladach
Is na héin ag eitilt ard
Tá grá mo chroí san áit seo
I measc na gcrann is na mbláth

[Chorus]
Seo í mo amhrán, seo í mo ghlór
Ag canadh le gaoth an tsléibhe
Ó chroí go croí, ó ghlúin go glúin
Beidh an ceol seo beo go deo', 'Irish Gaelic Folk', 100, 'A Major', 'S_INST200 session5 Strophic, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (228, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI174', 'Hawaiian Slack-key featuring Hawaiian vocals. Slack-key guitar plays open-tuned fingerpicked patterns with resonant bass drones and cascading treble harmonics that ring with natural overtones. Ukulele provides bright rhythmic strumming with gentle syncopated patterns and warm nylon-string chime. Steel guitar delivers smooth sustained slides with glassy tone and long portamento bends that float above the rhythm. The vocals feature a warm relaxed delivery with gentle falsetto passages and natural Hawaiian vowel flow. The arrangement is breezy and unhurried, with the slack-key guitar''s open tuning creating a rich self-accompanying texture. 85 BPM in Bb Major, 4/4 time signature.', '[Verse 1]
Ke aloha o ka moana
Ka makani honi mai
Nā pua o ka āina
E mohala i ka lā

[Chorus]
Aloha nō, aloha nō
Ka nani o Hawai''i
E ho''i mai, e ho''i mai
I ka home i ka pili

[Verse 2]
Ka ua e haule ana
Ma luna o ka pali
Ke ao nani o ke ahiahi
Me ka hōkū holomua

[Chorus]
Aloha nō, aloha nō
Ka nani o Hawai''i
E ho''i mai, e ho''i mai
I ka home i ka pili', 'Hawaiian Slack-key', 85, 'Bb Major', 'S_INST200 session5 Strophic, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (229, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI175', 'Turkish Folk featuring Turkish vocals. Bağlama plays rapid tremolo-picked melodic phrases with bright metallic string resonance and ornamental slides between microtonal intervals. Ney provides haunting breathy sustained tones with subtle overblowing and gentle pitch bends that weave through the modal scale. Frame drum delivers the aksak rhythm with alternating deep dum strokes and crisp tek accents in the asymmetric 9/8 pattern. The vocals feature a powerful nasal delivery with melismatic ornamental runs and dramatic emotional peaks. The arrangement is raw and earthy, with the bağlama and voice commanding the melodic foreground. 88 BPM in Eb Phrygian, 9/8 time signature.', '[Verse 1]
Dağların ardında güneş batıyor
Yüreğim hasretle yanıp tutuyor
Rüzgâr estiğinde sesin geliyor
Gözlerim yollarda seni arıyor

[Chorus]
Gel sevdim gel, dön artık gel
Bu gurbet elde kaldım ben
Senin için yandım yandım
Bir ömür boyu bekledim

[Verse 2]
Çeşmeler akar da suyu kurumaz
Ayrılık acısı gönülden çıkmaz
Bahar gelir gider yaz bitmez
Ama sensiz hiçbir şey güzel olmaz

[Chorus]
Gel sevdim gel, dön artık gel
Bu gurbet elde kaldım ben
Senin için yandım yandım
Bir ömür boyu bekledim', 'Turkish Folk', 88, 'Eb Phrygian', 'S_INST200 session5 Strophic, 9/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (230, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI176', 'Reggaeton instrumental. Dembow rhythm delivers the signature syncopated kick-snare pattern with a bouncing two-bar loop and sharp clap accents that drive the infectious groove. Staccato synth bass provides short punchy low-end hits with filtered resonance and rhythmic sidechain pumping that locks with the dembow. Atmospheric pad plays sustained filtered chords with warm harmonic texture and slow modulation that fills the midrange. The arrangement is stripped and percussive, with the dembow pattern maintaining relentless dancefloor momentum. 95 BPM in C# Minor, 4/4 time signature.', NULL, 'Reggaeton', 95, 'C# Minor', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (231, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI177', 'Garage Rock instrumental. Overdriven guitar plays raw power chord riffs with fuzzy distortion and aggressive downstroke strumming that buzzes with unpolished energy. Bass guitar delivers a thick driving root-note foundation with heavy pick attack and distorted midrange growl. Lo-fi drums feature a loose energetic pattern with crashing cymbals and booming floor tom fills that sound like a live room recording. The arrangement is raw and unrefined, with deliberate sonic imperfections and garage-band energy that prioritizes attitude over polish. 150 BPM in A Minor, 4/4 time signature.', NULL, 'Garage Rock', 150, 'A Minor', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (232, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI178', 'New Wave instrumental. Sequenced synth plays bright arpeggiated patterns with thin analog oscillator tone and rhythmic pulse-width modulation that creates a shimmering texture. Fretless bass provides smooth legato melodic lines with warm rounded tone and expressive slides between notes. Electronic drums deliver a tight programmed pattern with gated snare reverb and crisp synthetic hi-hats. The arrangement is clean and angular, with the synth arpeggios driving a polished retro-futuristic aesthetic. 135 BPM in Bb Major, 4/4 time signature.', NULL, 'New Wave', 135, 'Bb Major', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (233, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI179', 'Synth Punk instrumental. Distorted synth plays aggressive buzzing riffs with square-wave distortion and rapid staccato note patterns that attack with abrasive intensity. Aggressive bass delivers a thick overdriven low-end with fast eighth-note runs and punchy palm-muted accents. Four-on-the-floor kick provides a relentless driving pulse with hard-clipped transients and snare backbeats that slam with maximum impact. The arrangement is confrontational and high-speed, with no reverb and in-your-face dry production that amplifies the raw aggression. 162 BPM in C# Minor, 4/4 time signature.', NULL, 'Synth Punk', 162, 'C# Minor', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (234, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI180', 'Space Rock instrumental. Reverb guitar plays sustained tremolo-picked chords with deep spring reverb and cascading delay trails that stretch into infinite cosmic decay. Synthesizer provides evolving atmospheric textures with slow filter sweeps and ethereal pad layers that shimmer across the stereo field. Echo drums deliver a spacious pattern with delay-treated snare hits and distant ride cymbal washes that blur into the ambient wash. The arrangement is vast and weightless, with each element dissolving into layers of reverb and delay. 100 BPM in Eb Minor, 4/4 time signature.', NULL, 'Space Rock', 100, 'Eb Minor', 'S_INST200 session5 Through-composed, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (235, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI181', 'Boogie instrumental. Talk box guitar plays melodic vocal-like phrases with filtered vowel articulations and bright funk-inflected riffs that shimmer with processed harmonic overtones. Bass guitar provides a deep syncopated groove with slapped attacks and popping octave jumps that bounce with funky energy. Electronic drums deliver a tight four-on-the-floor pattern with crisp hi-hat accents and punchy clap backbeats that maintain a steady dancefloor pulse. The arrangement is groovy and retro, with the talk box carrying the melodic lead above a tight rhythmic foundation. 112 BPM in Ab Minor, 4/4 time signature.', NULL, 'Boogie', 112, 'Ab Minor', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (236, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI182', 'City Pop instrumental. Slap bass plays bright melodic grooves with crisp thumb slaps and popping upper-octave runs that drive a sophisticated rhythmic foundation. Clean electric guitar provides warm chorus-treated chord voicings with jazzy extended harmonies and smooth arpeggiated fills. Electric piano delivers lush sustained pads with warm tremolo and bell-like upper-register accents that add harmonic richness. The arrangement is polished and breezy, with a late-night urban sophistication and warm analog production aesthetic. 110 BPM in F# Major, 4/4 time signature.', NULL, 'City Pop', 110, 'F# Major', 'S_INST200 session5 Verse-Chorus-Bridge, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (237, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI183', 'K-Pop Dance instrumental. Synthesizer plays bright melodic hooks with layered sawtooth tones and rapid staccato patterns that create an energetic pop texture. Sub-bass provides deep sustained low-frequency hits with sidechain compression and occasional pitch drops that add weight beneath the melody. Crisp snare delivers tight electronic backbeats with layered clap samples and punchy attack that cuts through the dense arrangement. The arrangement is maximalist and dynamic, with dramatic build-ups and explosive chorus drops. 125 BPM in Db Minor, 4/4 time signature.', NULL, 'K-Pop Dance', 125, 'Db Minor', 'S_INST200 session5 Verse-Chorus-Bridge, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (238, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI184', 'K-Indie instrumental. Clean electric guitar plays soft arpeggiated patterns with warm chorus effect and gentle hammer-on embellishments that create a dreamy melodic texture. Soft synth pad provides sustained atmospheric chords with slow filter movement and warm harmonic layering. Light drums deliver an understated pattern with soft brushed snare and delicate hi-hat taps that barely mark the beat. The arrangement is airy and introspective, with generous empty space and a gentle dynamic arc that never pushes past a soft midpoint. 100 BPM in Bb Major, 4/4 time signature.', NULL, 'K-Indie', 100, 'Bb Major', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (239, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI185', 'K-Rock instrumental. Distorted guitar plays aggressive palm-muted riffs with thick crunch and explosive open-chord power sections that alternate between tight restraint and full-frequency release. Palm-muted riffs deliver rapid sixteenth-note chugging patterns with precision downpicking and harmonic pinch accents. Driving drums feature a relentless double-time pattern with crashing cymbals and powerful kick-snare combinations that propel the intensity forward. The arrangement is dynamic and hard-hitting, with quiet-to-loud contrasts and building instrumental crescendos. 138 BPM in Ab Minor, 4/4 time signature.', NULL, 'K-Rock', 138, 'Ab Minor', 'S_INST200 session5 Verse-Chorus-Bridge, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (240, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI186', 'Microtonal Experiment instrumental. Microtonal synthesizer plays quarter-tone melodic phrases with unfamiliar interval spacings and slowly bending pitch contours that drift between conventional tuning boundaries. Detuned piano provides percussive prepared-piano-like attacks with intentionally mistuned strings that create beating interference patterns. Percussion delivers sparse rhythmic accents with metallic strikes and muted resonant hits that punctuate the asymmetric 5/4 meter. The arrangement is exploratory and disorienting, treating pitch as a continuous spectrum rather than discrete steps. 75 BPM in Quarter-tone D, 5/4 time signature.', NULL, 'Microtonal Experiment', 75, 'Quarter-tone D', 'S_INST200 session5 Free-form, 5/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (241, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI187', 'Polyrhythm Study instrumental. Marimba plays interlocking melodic patterns with bright wooden resonance and rapid mallet alternations that create phasing rhythmic textures. Djembe provides layered hand-drum patterns with deep bass tones and crisp slap accents that establish a polyrhythmic grid against the marimba. Shakers deliver a continuous high-frequency pulse with subtle dynamic swells and steady sixteenth-note patterns that anchor the shifting rhythmic landscape. The arrangement is hypnotic and mathematically precise, with overlapping cycles that align and diverge across the 7/8 meter. 110 BPM in Ab Major, 7/8 time signature.', NULL, 'Polyrhythm Study', 110, 'Ab Major', 'S_INST200 session5 Through-composed, 7/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (242, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI188', 'Silence Study instrumental. Prepared piano plays isolated single notes with damped metallic resonance and extended silences between each sparse attack. Long pauses function as structural elements with room tone and the natural decay of each note filling the negative space. Single bell provides rare punctuating strikes with long shimmering sustain and pure overtone resonance that rings into extended silence. The arrangement treats absence as the primary material, with sound appearing as brief interruptions in an otherwise empty field. 25 BPM in Db Major, 4/4 time signature.', NULL, 'Silence Study', 25, 'Db Major', 'S_INST200 session5 Free-form, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (243, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI189', 'Feedback Noise instrumental. Guitar feedback provides a sustained high-pitched oscillation with overtone-rich screaming harmonics and unpredictable pitch fluctuations. Noise generator delivers a harsh broadband static wall with aggressive distortion and modulated intensity that surges in chaotic waves. Industrial drums feature pounding mechanical kick patterns with metallic clanking percussion and distorted snare bursts at punishing tempo. The arrangement is abrasive and relentless, with no melodic content and pure sonic violence as the compositional intent. 220 BPM in Atonal, 4/4 time signature.', NULL, 'Feedback Noise', 220, 'Atonal', 'S_INST200 session5 Free-form, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (244, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI190', 'Binaural Drone instrumental. Binaural beat synth provides a slowly pulsing stereo-separated tone with gentle frequency difference creating a perceptual beating effect. Sub-bass oscillator delivers a deep continuous fundamental tone with barely perceptible pitch modulation and immense low-frequency presence. Wind texture adds an organic atmospheric layer with filtered noise and gentle dynamic variation that simulates natural airflow. The arrangement is purely immersive and meditative, designed as a continuous sonic environment rather than a composed piece. 30 BPM in F Minor, 4/4 time signature.', NULL, 'Binaural Drone', 30, 'F Minor', 'S_INST200 session5 Free-form, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (245, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI191', 'Pentatonic Ambient instrumental. Crystal singing bowls play sustained tones with pure overtone resonance and slowly evolving harmonic interactions between overlapping pitches. Synth pad provides a warm atmospheric bed with gentle pentatonic chord movement and soft filter breathing. Wind chimes enter with delicate randomized metallic tinkles and sparse high-frequency accents that sparkle across the ambient field. The arrangement is serene and floating, with no rhythmic pulse and each element blending into a continuous harmonic wash. 40 BPM in A Pentatonic, 4/4 time signature.', NULL, 'Pentatonic Ambient', 40, 'A Pentatonic', 'S_INST200 session5 Free-form, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (246, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI192', 'Chromatic Etude instrumental. Piano plays rapid chromatic scale passages with precise articulation and even dynamic control across ascending and descending runs. Violin provides a sustained legato counter-melody with expressive vibrato and chromatic voice-leading that shadows the piano movement. Cello delivers a deep anchoring foundation with long bowed pedal tones and occasional chromatic walking bass lines. The arrangement is technically demanding and tonally ambiguous, with all twelve pitch classes receiving equal weight. 90 BPM in Chromatic, 3/4 time signature.', NULL, 'Chromatic Etude', 90, 'Chromatic', 'S_INST200 session5 Through-composed, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (247, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI193', 'Lydian Dream instrumental. Electric piano plays warm sustained chords with the characteristic raised-fourth Lydian color and gentle tremolo modulation. Synth pad provides an ethereal atmospheric layer with slow-attack swells and bright shimmering overtones that float above the harmonic foundation. Soft drums deliver a gentle compound-meter pattern with brushed snare and subdued kick that marks the 6/8 pulse without imposing. The arrangement is luminous and weightless, with the Lydian mode creating a sense of perpetual upward lift. 82 BPM in F Lydian, 6/8 time signature.', NULL, 'Lydian Dream', 82, 'F Lydian', 'S_INST200 session5 Verse-Chorus, 6/8', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (248, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI194', 'Aeolian Rock instrumental. Clean guitar plays arpeggiated chord progressions with natural minor color and warm reverb-treated tone that rings with open-string resonance. Bass guitar provides a steady eighth-note foundation with round fingered tone and root-fifth movement that anchors the Aeolian harmony. The drums feature a driving midtempo pattern with crisp snare backbeats and steady hi-hat eighths that maintain a solid rock groove. The arrangement is melodic and melancholic, with the natural minor mode creating a contemplative darkness. 112 BPM in A Aeolian, 4/4 time signature.', NULL, 'Aeolian Rock', 112, 'A Aeolian', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (249, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI195', 'Dulcimer Folk instrumental. Hammered dulcimer plays bright cascading melodic runs with rapid mallet strikes and ringing sustained overtones that shimmer across the treble register. Fiddle provides warm melodic counter-phrases with legato bowing and quick ornamental turns that add folk embellishment. Acoustic guitar delivers steady fingerpicked accompaniment with warm steel-string resonance and alternating bass-note patterns. The arrangement is pastoral and lively, with the dulcimer''s crystalline brightness dancing above the earthy accompaniment. 98 BPM in Db Major, 3/4 time signature.', NULL, 'Dulcimer Folk', 98, 'Db Major', 'S_INST200 session5 Strophic, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (250, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI196', 'Zither Classical instrumental. Zither plays delicate melodic phrases with bright plucked metallic strings and gentle tremolo passages that resonate with natural overtones. Violin provides a warm lyrical counter-melody with sustained legato bowing and expressive vibrato. Cello delivers deep sustained harmonic support with rich low-register bowing and gentle pizzicato accents. The arrangement is refined and intimate, with each instrument occupying a distinct acoustic space in a chamber setting. 65 BPM in F# Minor, 3/4 time signature.', NULL, 'Zither Classical', 65, 'F# Minor', 'S_INST200 session5 Through-composed, 3/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (251, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI197', 'Ukulele Pop instrumental. Ukulele plays bright strummed chord progressions with cheerful nylon-string warmth and syncopated rhythmic accents that bounce with playful energy. Light percussion provides a gentle pattern with soft claps and shaker that maintain a relaxed groove. Bass delivers warm round low-end support with simple root-note patterns and occasional melodic fills. The arrangement is sunny and carefree, with the ukulele''s bright tone carrying an effortlessly uplifting mood. 118 BPM in Bb Major, 4/4 time signature.', NULL, 'Ukulele Pop', 118, 'Bb Major', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (252, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI198', 'Melodica Reggae instrumental. Melodica plays warm sustained melodic phrases with breathy keyboard tone and gentle pitch bends that sway with the offbeat pulse. Heavy bass provides deep sustained root notes with round tube-amp warmth and occasional octave drops that anchor the reggae groove. Spring reverb snare delivers a sharp crack with long metallic reverb decay and offbeat accents that define the classic one-drop pattern. The arrangement is laid-back and rootsy, with the melodica''s organic breath-driven tone adding a human quality above the deep bass foundation. 76 BPM in Eb Major, 4/4 time signature.', NULL, 'Melodica Reggae', 76, 'Eb Major', 'S_INST200 session5 Verse-Chorus, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (253, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI199', 'Cimbalom Jazz instrumental. Cimbalom plays rapid melodic runs with bright metallic hammer strikes and shimmering tremolo passages that ring with overtone-rich resonance. Upright bass provides a warm walking line with legato fingered notes and subtle rhythmic swing. Brush drums deliver soft swishing patterns with gentle ride cymbal taps and understated kick accents that maintain a relaxed jazz feel. The arrangement is intimate and conversational, with the cimbalom''s unique metallic brightness adding an Eastern European color to a classic jazz trio format. 100 BPM in Db Minor, 4/4 time signature.', NULL, 'Cimbalom Jazz', 100, 'Db Minor', 'S_INST200 session5 AABA, 4/4', 'experimental');
INSERT INTO songs_test_lab (test_id, batch, source_project, creator, title, style_prompt, lyrics, genre, bpm, key_signature, note, status) VALUES (254, 'S_INST200', 'sunolanguage', 'sunolanguage', 'SI200', 'Glass Harmonica instrumental. Glass harmonica plays ethereal sustained tones with pure crystalline resonance and slowly evolving melodic phrases that shimmer with glassy overtones. Harp provides gentle arpeggiated accompaniment with soft plucked attacks and cascading harmonic sweeps. Sustained strings deliver a warm atmospheric bed with long legato bowing and gentle dynamic swells that breathe beneath the glass harmonica''s otherworldly tone. The arrangement is delicate and celestial, with each element contributing to a translucent sonic tapestry. 50 BPM in Ab Major, 3/4 time signature.', NULL, 'Glass Harmonica', 50, 'Ab Major', 'S_INST200 session5 Through-composed, 3/4', 'experimental');
